function checkQuota(tenantId, byteSize, policyStore, quotas) {
  const q = policyStore[tenantId] || quotas.default;
  if (q.bytesUsed + byteSize > q.bytesLimit) return false;
  q.bytesUsed += byteSize;
  return true;
}
```

